package com.drivique.api.controller;import com.drivique.api.dto.*;import com.drivique.api.service.ReviewService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1") public class ReviewController{private final ReviewService service;public ReviewController(ReviewService service){this.service=service;}@PostMapping("/reviews/vehicles") @ResponseStatus(HttpStatus.CREATED) public void vehicle(@Valid @RequestBody ReviewRequestDTO input,Authentication a){service.rateVehicle(input,a.getName());}@PostMapping("/reviews/branches") @ResponseStatus(HttpStatus.CREATED) public void branch(@Valid @RequestBody BranchReviewRequestDTO input,Authentication a){service.reviewBranch(input,a.getName());}@GetMapping("/vehicles/{id}/reviews") public VehicleReviewsResponseDTO list(@PathVariable UUID id){return service.vehicleReviews(id);}}
